import { useState, useEffect, useRef } from 'react';
import './Hero.css';

const PHRASES = [
  'Full Stack Developer',
  'React Enthusiast',
  'Node.js Learner',
  'UI/UX Craftsman',
  'Junior Developer',
];

export default function Hero() {
  const [typed, setTyped] = useState('');
  const state = useRef({ pi: 0, ci: 0, del: false });
  const canvasRef = useRef(null);

  /* ── Typing effect ── */
  useEffect(() => {
    let timer;
    const tick = () => {
      const s = state.current;
      const cur = PHRASES[s.pi];
      if (s.del) { if (s.ci > 0) s.ci--; }
      else { if (s.ci < cur.length) s.ci++; }
      setTyped(cur.substring(0, s.ci));
      let spd = s.del ? 48 : 86;
      if (!s.del && s.ci === cur.length) { spd = 1600; s.del = true; }
      else if (s.del && s.ci === 0) { s.del = false; s.pi = (s.pi + 1) % PHRASES.length; spd = 400; }
      timer = setTimeout(tick, spd);
    };
    timer = setTimeout(tick, 600);
    return () => clearTimeout(timer);
  }, []);

  /* ── 3D Particle field ── */
  useEffect(() => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    let animId;
    let mouseX = 0, mouseY = 0;
    let smoothX = 0, smoothY = 0;

    const resize = () => {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    };
    resize();
    window.addEventListener('resize', resize);

    const particles = Array.from({ length: 100 }, () => ({
      x: (Math.random() - 0.5) * 1800,
      y: (Math.random() - 0.5) * 1800,
      z: Math.random() * 1800,
      size: Math.random() * 1.8 + 0.4,
      color: Math.random() > 0.5 ? '0,247,255' : '168,85,247',
    }));

    const onMove = e => {
      mouseX = (e.clientX / window.innerWidth - 0.5) * 2;
      mouseY = (e.clientY / window.innerHeight - 0.5) * 2;
    };
    window.addEventListener('mousemove', onMove);

    const draw = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      smoothX += (mouseX - smoothX) * 0.04;
      smoothY += (mouseY - smoothY) * 0.04;

      const cx = canvas.width / 2;
      const cy = canvas.height / 2;
      const fov = 500;

      const projected = particles.map(p => {
        p.z -= 2;
        if (p.z <= 0) p.z = 1800;
        const rx = p.x + smoothX * (p.z / 3.5);
        const ry = p.y + smoothY * (p.z / 3.5);
        const scale = fov / (fov + p.z);
        const sx = cx + rx * scale;
        const sy = cy + ry * scale;
        return { ...p, sx, sy, scale };
      });

      // lines
      for (let i = 0; i < projected.length; i++) {
        for (let j = i + 1; j < projected.length; j++) {
          const a = projected[i];
          const b = projected[j];
          if (a.sx < 0 || a.sx > canvas.width) continue;
          const dx = a.sx - b.sx;
          const dy = a.sy - b.sy;
          const dist = Math.sqrt(dx * dx + dy * dy);
          if (dist < 90) {
            ctx.beginPath();
            ctx.moveTo(a.sx, a.sy);
            ctx.lineTo(b.sx, b.sy);
            ctx.strokeStyle = `rgba(0,247,255,${(1 - dist / 90) * 0.12})`;
            ctx.lineWidth = 0.5;
            ctx.stroke();
          }
        }
      }

      // dots
      projected.forEach(p => {
        if (p.sx < 0 || p.sx > canvas.width || p.sy < 0 || p.sy > canvas.height) return;
        const size = p.size * p.scale * 2.5;

        const grd = ctx.createRadialGradient(p.sx, p.sy, 0, p.sx, p.sy, size * 4);
        grd.addColorStop(0, `rgba(${p.color},${p.scale * 0.9})`);
        grd.addColorStop(0.4, `rgba(${p.color},${p.scale * 0.3})`);
        grd.addColorStop(1, `rgba(${p.color},0)`);
        ctx.beginPath();
        ctx.arc(p.sx, p.sy, size * 4, 0, Math.PI * 2);
        ctx.fillStyle = grd;
        ctx.fill();

        ctx.beginPath();
        ctx.arc(p.sx, p.sy, size, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(${p.color},${p.scale})`;
        ctx.fill();
      });

      animId = requestAnimationFrame(draw);
    };
    draw();

    return () => {
      window.removeEventListener('mousemove', onMove);
      window.removeEventListener('resize', resize);
      cancelAnimationFrame(animId);
    };
  }, []);

  const scrollTo = (id) => {
    const el = document.getElementById(id);
    if (el) window.scrollTo({ top: el.offsetTop - 70, behavior: 'smooth' });
  };

  /* ── Name 3D parallax ── */
  useEffect(() => {
    const name = document.getElementById('name3d');
    if (!name) return;

    const onMove = e => {
      const cx = window.innerWidth / 2;
      const cy = window.innerHeight / 2;
      const dx = (e.clientX - cx) / cx;
      const dy = (e.clientY - cy) / cy;

      name.style.transform = `rotateY(${dx * 18}deg) rotateX(${-dy * 10}deg)`;
      name.style.filter = `drop-shadow(${dx * 18}px ${dy * 8}px 24px rgba(0,247,255,0.7)) drop-shadow(${-dx * 14}px ${-dy * 6}px 20px rgba(168,85,247,0.6))`;

      const letters = name.querySelectorAll('.name-letter');
      letters.forEach((l, i) => {
        const depth = (i / 7) - 0.5;
        l.style.transform = `translateZ(${depth * dx * 60}px) translateX(${depth * dx * 12}px)`;
        l.style.textShadow = `
        ${dx * 8 * (i + 1) * 0.15}px ${dy * 6}px 0px rgba(0,247,255,0.4),
        ${-dx * 6 * (i + 1) * 0.15}px ${-dy * 4}px 0px rgba(168,85,247,0.4),
        0 0 40px rgba(0,247,255,${0.3 + Math.abs(dx) * 0.4})
      `;
      });
    };

    const onLeave = () => {
      name.style.transform = '';
      name.style.filter = '';
      name.querySelectorAll('.name-letter').forEach(l => {
        l.style.transform = '';
        l.style.textShadow = '';
      });
    };

    window.addEventListener('mousemove', onMove);
    document.querySelector('.hero')?.addEventListener('mouseleave', onLeave);

    return () => {
      window.removeEventListener('mousemove', onMove);
      document.querySelector('.hero')?.removeEventListener('mouseleave', onLeave);
    };
  }, []);
  return (
    <section id="home" className="hero">

      <canvas ref={canvasRef} className="hero-canvas" />

      <div className="shooting-stars">
        {[...Array(20)].map((_, i) => (
          <div
            key={i}
            className={i % 3 === 0 ? 'shoot shoot-purple' : i % 3 === 1 ? 'shoot shoot-white' : 'shoot'}
            style={{
              '--i': i % 6,
              top: (i * 4.7) % 88 + '%',
              animationDelay: i * 0.55 + 's',
              height: 35 + i * 7 + 'px',
            }}
          />
        ))}
      </div>

      <div className="hero-badge">
        <span className="badge-dot" />
        Available for Work — Junior Developer
      </div>

      <div className="hero-content">
        <p className="hero-eye">Hello World 👋</p>
        <h1>I'm <span className="name-3d" id="name3d">
          {'M Ahmad'.split('').map((ch, i) => (
            <span key={i} className="name-letter" style={{ '--i': i }}>
              {ch === ' ' ? '\u00A0' : ch}
            </span>
          ))}
        </span></h1>
        <div className="typing-wrap">
          <span>{typed}</span>
          <span className="blink">|</span>
        </div>
        <p className="hero-sub">
          Building modern full-stack web experiences — pixel-perfect frontends &amp; clean backends.
        </p>
        <div className="hero-ctas">
          <a href="./images/resume.pdf" download className="btn btn-p">
            <i className="fa-solid fa-download" /> Download Resume
          </a>
          <button className="btn btn-g" onClick={() => scrollTo('projects')}>
            View Work <i className="fa-solid fa-arrow-right" />
          </button>
        </div>
      </div>

      <div className="scroll-ind">
        <div className="scroll-line" />
        <span>Scroll</span>
      </div>
    </section>
  );
}
